  "temp_cat_9012": {
    "id": "temp_cat_9012",
    "title": "Knowledge Base (KB) Generation",
    "description": "Guides and procedures for using the automated Knowledge Base Generation feature.",
    "articles": [
      {
        "id": "temp_art_5587",
        "title": "KB Generation Dashboard Overview",
        "content": {
          "type": "doc",
          "content": [
            {
              "type": "heading",
              "attrs": {
                "level": 2,
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "Understanding the Dashboard"
                }
              ]
            },
            {
              "type": "paragraph",
              "attrs": {
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "The KB Generation Dashboard is the starting point for creating a knowledge base from your source files. You can access it via the breadcrumb navigation: Platform > KB Generation."
                }
              ]
            },
            {
              "type": "paragraph",
              "attrs": {
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "If there are no ongoing jobs, the dashboard will display a message stating \"No Active Content Generation Job\"."
                }
              ]
            }
          ]
        }
      },
      {
        "id": "temp_art_5588",
        "title": "How to Start a Content Generation Job",
        "content": {
          "type": "doc",
          "content": [
            {
              "type": "heading",
              "attrs": {
                "level": 2,
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "Starting a New Job"
                }
              ]
            },
            {
              "type": "paragraph",
              "attrs": {
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "To begin the process, you must upload the source files you want to use for generating the knowledge base."
                }
              ]
            },
            {
              "type": "paragraph",
              "attrs": {
                "provenance": {
                  "sourceFile": "gs://ecoms-ai-kb-generation-dashboard.png"
                }
              },
              "content": [
                {
                  "type": "text",
                  "text": "Click the \"+ Upload New Content\" button located in the center of the KB Generation Dashboard to get started."
                }
              ]
            }
          ]
        }
      }
    ]
